def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def heightsAfterRemoval(tree, queries):
    vals, left, right = _links(tree)
    n = len(vals)
    depth = [0] * n
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                depth[c] = depth[k] + 1
    height = [0] * n
    for k in range(n - 1, -1, -1):
        for c in (left[k], right[k]):
            if c != -1:
                height[k] = max(height[k], height[c] + 1)
    top1 = {}   # depth -> (value, node)
    top2 = {}   # depth -> value
    for k in range(n):
        d = depth[k]
        v = depth[k] + height[k]
        if d not in top1 or v > top1[d][0]:
            if d in top1:
                top2[d] = top1[d][0]
            top1[d] = (v, k)
        elif v > top2.get(d, -1):
            top2[d] = v
    node_of = {vals[k]: k for k in range(n)}
    out = []
    for q in queries:
        k = node_of[q]
        d = depth[k]
        rest = top2.get(d, -1) if top1[d][1] == k else top1[d][0]
        out.append(max(d - 1, rest))
    return out
